selector_to_html = {"a[href=\"#tle\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">TLE \u6269\u5c55\u64cd\u4f5c<a class=\"headerlink\" href=\"#tle\" title=\"Link to this heading\">#</a></h2><p>Arm64 \u540e\u7aef\u6ce8\u518c\u4e86 6 \u4e2a\u6269\u5c55\u64cd\u4f5c\uff0c\u8986\u76d6 GEMV / \u5f52\u4e00\u5316 / \u6fc0\u6d3b / \u6ce8\u610f\u529b\u7b49\u89e3\u7801\u70ed\u70b9\uff0c\u6bcf\u4e2a\u5bf9\u5e94\u4e00\u4e2a\u547d\u540d\u7684\u5f20\u91cf\u64cd\u4f5c\u3002\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">@triton.jit</span></code> \u4e2d\u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">triton.language.extra.cpu.tle_ops</span></code> \u8c03\u7528\u3002</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6982\u8ff0<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>Arm64 \u662f TLE-CPU \u9996\u4e2a\u5b8c\u6574\u5b9e\u73b0\u7684\u540e\u7aef\uff0c\u76ee\u6807\u5e73\u53f0\u4e3a Arm v9-A\uff08NEON / SVE2 + i8mm + bf16\uff09\uff0c\u53c2\u8003\u786c\u4ef6\u4e3a CIX P1\uff08CD8180\uff0c8\u00d7 Cortex-A720 \u5927\u6838 + 4\u00d7 A520 \u5c0f\u6838\uff09\u3002</p><p>\u8f6f\u4ef6\u57fa\u7ebf\uff1aTriton 3.3 / LLVM a66376b0 / PyTorch 2.10 (CPU) / Python 3.11\u3002</p>", "a[href=\"#arm64\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Arm64<a class=\"headerlink\" href=\"#arm64\" title=\"Link to this heading\">#</a></h1><h2>\u6982\u8ff0<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>Arm64 \u662f TLE-CPU \u9996\u4e2a\u5b8c\u6574\u5b9e\u73b0\u7684\u540e\u7aef\uff0c\u76ee\u6807\u5e73\u53f0\u4e3a Arm v9-A\uff08NEON / SVE2 + i8mm + bf16\uff09\uff0c\u53c2\u8003\u786c\u4ef6\u4e3a CIX P1\uff08CD8180\uff0c8\u00d7 Cortex-A720 \u5927\u6838 + 4\u00d7 A520 \u5c0f\u6838\uff09\u3002</p><p>\u8f6f\u4ef6\u57fa\u7ebf\uff1aTriton 3.3 / LLVM a66376b0 / PyTorch 2.10 (CPU) / Python 3.11\u3002</p>", "a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8bbe\u8ba1\u8981\u70b9\uff1a\u8c03\u5ea6\u5373\u6027\u80fd<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>\u89e3\u7801\u74f6\u9888\u5f80\u5f80\u4e0d\u662f\u7b97\u529b\uff0c\u800c\u662f\u7b97\u5b50\u8c03\u5ea6\u6b21\u6570\uff08\u7eaf ATen \u57fa\u7ebf\u7ea6\u6bcf\u4e2a token \u6570\u5343\u6b21\u8c03\u5ea6\uff09\u3002\u52a0\u901f\u6709\u4e24\u4e2a\u6b63\u4ea4\u7684\u7ef4\u5ea6\uff1a</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528\u793a\u4f8b<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">rms_norm</span></code> \u7aef\u5230\u7aef\uff08<code class=\"docutils literal notranslate\"><span class=\"pre\">@triton.jit</span></code> \u2192 <code class=\"docutils literal notranslate\"><span class=\"pre\">create_cpu_rms_norm</span></code> \u2192 NEON \u8fd0\u884c\u65f6\uff09\uff1a</p>", "a[href=\"#arm64-lowering\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Arm64 lowering \u8def\u5f84<a class=\"headerlink\" href=\"#arm64-lowering\" title=\"Link to this heading\">#</a></h3><p>\u6269\u5c55\u64cd\u4f5c\u7ecf\u8fc7 TritonCPU \u65b9\u8a00\u540e\uff0c\u6839\u636e lowering \u65b9\u5f0f\u5206\u4e3a\u4e24\u6761\u8def\u5f84\uff1a</p>", "a[href=\"#id6\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u7ebf\u7a0b\u6a21\u578b\u4e0e\u8c03\u4f18<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h3><p><strong>\u7ebf\u7a0b\u6a21\u578b</strong>\uff1a\u5e76\u884c\u7531 TLE \u8fd0\u884c\u65f6\u81ea\u884c\u7ba1\u7406\u3002\u5728\u901a\u8fc7 torch \u6267\u884c\u63a8\u7406\u7684\u573a\u666f\u4e2d\uff08\u5982 HF Transformers\uff09\uff0c</p><p>\u8ba1\u7b97\u5bc6\u96c6\u578b\u90e8\u5206\u7684\u7ebf\u7a0b\u7ea7\u5e76\u884c\u5728 TLE \u8fd0\u884c\u65f6\u5185\u6838\u5185\u90e8\u542f\u52a8\u2014\u2014<code class=\"docutils literal notranslate\"><span class=\"pre\">runtime_*.cpp</span></code> \u4e2d\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">#pragma</span> <span class=\"pre\">omp</span> <span class=\"pre\">parallel</span></code>\uff0c\u6cbf N \u7ef4\u5ea6 / head \u7ef4\u5ea6\u5206\u533a\u2014\u2014\u800c\u975e\u901a\u8fc7 torch \u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">at::parallel_for</span></code> \u6216\u5176 intra-op \u7ebf\u7a0b\u6c60\u3002\u4e24\u9879\u914d\u7f6e\u786e\u4fdd TLE \u7684 OMP \u4e0d\u4e0e torch \u4e89\u62a2\u6838\u5fc3\uff1a</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u6269\u5c55\u64cd\u4f5c\u6c47\u603b<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id3\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u6570\u636e\u7ea6\u5b9a<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">sm_scale</span></code> \u901a\u5e38\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">head_dim^-0.5</span></code>\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
